// L8a's int8 bank an identity for it (D13) — and is what `Src` selects on.
func (p QuantPlan) For(name string, q8Source bool) (QuantSim, bool) {
	if p.Off() {
		return QuantSim{}, false
	}
	fam := simFamily(name)
	if fam == "" {
		return QuantSim{}, false
	}
	q, ok := p.byFamily[fam]
	if !ok {
		return QuantSim{}, false
	}
