			// so the quantisation has to be against the *stored* value or
			// the levels are not the ones a kernel would pick.
			ds := safetensors.F16ToF32(safetensors.F32ToF16(d))
			if ds == 0 {
				continue
			}
			id := 1 / ds
			for i, v := range blk {
				l := roundHalfAway(v * id)
				if l < lo {
					l = lo
				}
				if l > hi {
					l = hi
				}
